 useEffect(()=>{if(!authUser?.uid)return;return onSnapshot(doc(db,'farmerProfiles',authUser.uid),snap=>{if(snap.exists()){setForm({...blank,...snap.data()});setSaved(true)}},e=>setMessage('Could not load profile: '+e.message))},[authUser?.uid]);
